  1	import java.util.Arrays;
  2	
  3	final class BellmanFord {
  4	    private static final int INF = 100_000_000;
  5	    private static final int NEGATIVE_CYCLE_MARKER = -1;
  6	    private static final int FROM_INDEX = 0;
  7	    private static final int TO_INDEX = 1;
  8	    private static final int WEIGHT_INDEX = 2;
  9	    private static final int EDGE_FIELD_COUNT = 3;
 10	
 11	    private BellmanFord() {
 12	    }
 13	
 14	    static int[] bellmanFord(int vertexCount, int[][] edgeData, int source) {
 15	        Graph graph = Graph.from(vertexCount, edgeData);
 16	        graph.validateSource(source);
 17	        return shortestPathsFrom(graph, source);
 18	    }
 19	
 20	    private static int[] shortestPathsFrom(Graph graph, int source) {
 21	        int[] distances = initialDistances(graph.vertexCount, source);
 22	
 23	        for (int i = 1; i < graph.vertexCount; i++) {
 24	            if (!relaxEdges(graph.edges, distances)) {
 25	                break;
 26	            }
 27	        }
 28	
 29	        if (hasReachableNegativeCycle(graph.edges, distances)) {
 30	            return negativeCycleResult();
 31	        }
 32	
 33	        return distances;
 34	    }
 35	
 36	    private static int[] initialDistances(int vertexCount, int source) {
 37	        int[] distances = new int[vertexCount];
 38	        Arrays.fill(distances, INF);
 39	        distances[source] = 0;
 40	        return distances;
 41	    }
 42	
 43	    private static int[] negativeCycleResult() {
 44	        return new int[]{NEGATIVE_CYCLE_MARKER};
 45	    }
 46	
 47	    private static boolean relaxEdges(Edge[] edges, int[] distances) {
 48	        boolean changed = false;
 49	
 50	        for (Edge edge : edges) {
 51	            if (edge.relax(distances)) {
 52	                changed = true;
 53	            }
 54	        }
 55	
 56	        return changed;
 57	    }
 58	
 59	    private static boolean hasReachableNegativeCycle(Edge[] edges, int[] distances) {
 60	        for (Edge edge : edges) {
 61	            if (edge.canRelax(distances)) {
 62	                return true;
 63	            }
 64	        }
 65	
 66	        return false;
 67	    }
 68	
 69	    private static final class Edge {
 70	        private final int from;
 71	        private final int to;
 72	        private final int weight;
 73	
 74	        private Edge(int from, int to, int weight) {
 75	            this.from = from;
 76	            this.to = to;
 77	            this.weight = weight;
 78	        }
 79	
 80	        private boolean isWithin(int vertexCount) {
 81	            return from >= 0 && from < vertexCount && to >= 0 && to < vertexCount;
 82	        }
 83	
 84	        private boolean relax(int[] distances) {
 85	            if (!canRelax(distances)) {
 86	                return false;
 87	            }
 88	
 89	            distances[to] = distances[from] + weight;
 90	            return true;
 91	        }
 92	
 93	        private boolean canRelax(int[] distances) {
 94	            return distances[from] != INF && distances[from] + weight < distances[to];
 95	        }
 96	    }
 97	
 98	    private static final class Graph {
 99	        private final int vertexCount;
100	        private final Edge[] edges;
101	
102	        private Graph(int vertexCount, Edge[] edges) {
103	            this.vertexCount = vertexCount;
104	            this.edges = edges;
105	        }
106	
107	        private static Graph from(int vertexCount, int[][] edgeData) {
108	            if (vertexCount < 0) {
109	                throw new IllegalArgumentException("Vertex count cannot be negative");
110	            }
111	
112	            if (edgeData == null) {
113	                throw new IllegalArgumentException("Edges cannot be null");
114	            }
115	
116	            Edge[] edges = new Edge[edgeData.length];
117	            for (int i = 0; i < edgeData.length; i++) {
118	                edges[i] = parseEdge(vertexCount, edgeData[i], i);
119	            }
120	
121	            return new Graph(vertexCount, edges);
122	        }
123	
124	        private static Edge parseEdge(int vertexCount, int[] edgeData, int index) {
125	            if (edgeData == null || edgeData.length != EDGE_FIELD_COUNT) {
126	                throw new IllegalArgumentException("Edge " + index + " must contain from, to, and weight");
127	            }
128	
129	            Edge edge = new Edge(edgeData[FROM_INDEX], edgeData[TO_INDEX], edgeData[WEIGHT_INDEX]);
130	            if (!edge.isWithin(vertexCount)) {
131	                throw new IllegalArgumentException("Edge " + index + " references a vertex outside the graph");
132	            }
133	
134	            return edge;
135	        }
136	
137	        private void validateSource(int source) {
138	            if (source < 0 || source >= vertexCount) {
139	                throw new IllegalArgumentException("Source vertex is out of range");
140	            }
141	        }
142	    }
143	
144	    public static void main(String[] args) {
145	
146	        int vertexCount = 5;
147	
148	        int[][] edges = new int[][] {
149	            {1, 3, 2},
150	            {4, 3, -1},
151	            {2, 4, 1},
152	            {1, 2, 1},
153	            {0, 1, 5}
154	        };
155	
156	        int source = 0;
157	
158	        int[] distances = bellmanFord(vertexCount, edges, source);
159	
160	        for (int distance : distances) {
161	            System.out.print(distance + " ");
162	        }
163	    }
164	}

